window.RECIPES_DATA = [{"id":"rendang-sapi","nama":"Rendang Daging Sapi","daerah_asal":"Minangkabau, Sumatera Barat","kategori":"Daging","porsi":6,"waktu_menit":240,"deskripsi":"Daging sapi dimasak perlahan bersama santan dan bumbu hingga berwarna gelap serta kaya rasa.","bahan":[{"nama":"Daging sapi","takaran":"1 kg"},{"nama":"Santan kental","takaran":"1 liter"},{"nama":"Serai, memarkan","takaran":"2 batang"},{"nama":"Daun jeruk","takaran":"5 lembar"},{"nama":"Daun kunyit","takaran":"1 lembar"},{"nama":"Bawang merah","takaran":"10 butir"},{"nama":"Bawang putih","takaran":"6 siung"},{"nama":"Cabai merah","takaran":"100–150 g, sesuaikan selera"},{"nama":"Jahe","takaran":"3 cm"},{"nama":"Lengkuas","takaran":"4 cm"},{"nama":"Kunyit","takaran":"3 cm"},{"nama":"Ketumbar","takaran":"1 sdm"},{"nama":"Garam","takaran":"secukupnya"}],"langkah":["Haluskan bawang merah, bawang putih, cabai, jahe, lengkuas, kunyit, dan ketumbar.","Masukkan bumbu halus, santan, serai, daun jeruk, dan daun kunyit ke dalam kuali; aduk dengan api sedang hingga mendidih.","Masukkan daging sapi, kecilkan api, lalu masak perlahan sambil sesekali diaduk agar tidak lengket.","Lanjutkan memasak hingga kuah menyusut, minyak keluar, dan daging empuk. Aduk lebih sering menjelang akhir.","Koreksi rasa dan sajikan."],"rempah_utama":["Serai","Daun jeruk","Daun kunyit","Jahe","Lengkuas","Kunyit","Ketumbar"],"nilai_budaya":"Rendang berkaitan erat dengan tradisi Minangkabau dan kerap hadir dalam perayaan serta jamuan adat.","fun_fact":"Rendang merupakan makanan tradisional masyarakat Minangkabau dari Sumatera Barat yang telah diwariskan secara turun-temurun. Sejarahnya berkaitan erat dengan tradisi merantau masyarakat Minangkabau, yang membawa makanan khas daerahnya ke berbagai wilayah di Nusantara, termasuk Semenanjung Malaya. Rendang juga memiliki hubungan dengan tradisi memasak daging berbumbu dalam acara adat, perayaan, dan penyambutan tamu. Meski asal-usul tepatnya belum dapat dipastikan, rendang telah lama menjadi bagian penting dari identitas budaya dan kuliner Minangkabau.\n\nRendang dimasak menggunakan daging sapi, santan, cabai, dan beragam rempah seperti lengkuas, serai, jahe, bawang merah, serta bawang putih. Proses memasak yang lama dengan api kecil hingga santan mengering membuat bumbu meresap ke dalam daging dan menghasilkan tekstur serta warna cokelat gelap yang khas. Kata randang diyakini berasal dari istilah marandang, yaitu teknik memasak santan hingga kering. Rendang ditetapkan sebagai Warisan Budaya Takbenda Indonesia pada 2013 dan menjadi simbol kekayaan kuliner Minangkabau.","gambar_url":"assets/images/masakan/rendang.jpg","sumber":"Resep prototipe untuk pengembangan aplikasi; perlu kurasi dan verifikasi lokal."},{"id":"soto-ayam-kuning","nama":"Soto Ayam Kuah Kuning","daerah_asal":"Jawa Timur","kategori":"Sup","porsi":4,"waktu_menit":45,"deskripsi":"Soto berkuah kuning dengan aroma kunyit, serai, daun jeruk, dan rempah pilihan.","bahan":[{"nama":"Ayam","takaran":"500–700 g"},{"nama":"Air","takaran":"1,5 liter"},{"nama":"Bawang merah","takaran":"6 butir"},{"nama":"Bawang putih","takaran":"4 siung"},{"nama":"Kunyit","takaran":"3 cm"},{"nama":"Jahe","takaran":"2 cm"},{"nama":"Kemiri","takaran":"3 butir"},{"nama":"Serai, memarkan","takaran":"2 batang"},{"nama":"Daun jeruk","takaran":"3 lembar"},{"nama":"Daun salam","takaran":"2 lembar"},{"nama":"Garam dan merica","takaran":"secukupnya"}],"langkah":["Rebus ayam dalam air hingga matang; simpan kaldunya dan suwir daging ayam.","Haluskan bawang merah, bawang putih, kunyit, jahe, dan kemiri.","Tumis bumbu halus hingga harum, lalu masukkan serai, daun jeruk, dan daun salam.","Masukkan tumisan ke dalam kaldu, bumbui dengan garam dan merica, lalu didihkan sekitar 15 menit.","Sajikan kuah bersama suwiran ayam dan pelengkap sesuai kebiasaan daerah."],"rempah_utama":["Kunyit","Jahe","Serai","Daun jeruk","Daun salam","Kemiri"],"nilai_budaya":"Soto memiliki banyak variasi daerah; komposisi bumbu dan pelengkapnya dapat berbeda antarwilayah dan keluarga.","gambar_url":"assets/images/masakan/soto_ayam_kuah_kuning.jpg","sumber":"Resep prototipe untuk pengembangan aplikasi; perlu kurasi dan verifikasi lokal."},{"id":"ayam-betutu","nama":"Ayam Betutu Bumbu Rajang","daerah_asal":"Bali","kategori":"Unggas","porsi":4,"waktu_menit":150,"deskripsi":"Ayam berbumbu lengkap dengan racikan rempah yang dimasak perlahan hingga meresap.","bahan":[{"nama":"Ayam utuh","takaran":"1 ekor (±1,2 kg)"},{"nama":"Bawang merah","takaran":"10 butir"},{"nama":"Bawang putih","takaran":"6 siung"},{"nama":"Cabai merah","takaran":"8 buah atau sesuai selera"},{"nama":"Kunyit","takaran":"4 cm"},{"nama":"Kencur","takaran":"3 cm"},{"nama":"Jahe","takaran":"3 cm"},{"nama":"Lengkuas","takaran":"4 cm"},{"nama":"Serai, iris halus","takaran":"3 batang"},{"nama":"Daun jeruk, iris","takaran":"5 lembar"},{"nama":"Ketumbar","takaran":"1 sdt"},{"nama":"Minyak","takaran":"3 sdm"},{"nama":"Garam","takaran":"secukupnya"}],"langkah":["Cuci dan keringkan ayam, lalu lumuri dengan sedikit garam.","Rajang halus atau haluskan bawang merah, bawang putih, cabai, kunyit, kencur, jahe, lengkuas, serai, dan daun jeruk.","Tumis bumbu dengan minyak hingga harum, lalu tambahkan ketumbar dan garam.","Lumuri ayam dengan bumbu hingga merata; sisipkan sebagian bumbu ke rongga ayam.","Masak tertutup dengan api kecil atau panggang hingga ayam matang dan bumbu meresap. Pastikan bagian terdalam ayam matang sempurna.","Diamkan sebentar, lalu sajikan."],"rempah_utama":["Kunyit","Kencur","Jahe","Lengkuas","Serai","Daun jeruk","Ketumbar"],"nilai_budaya":"Betutu dikenal sebagai olahan khas Bali; teknik, komposisi bumbu, dan cara penyajian dapat bervariasi menurut daerah dan keluarga.","fun_fact":"Ayam betutu merupakan makanan tradisional khas Bali yang memiliki sejarah panjang dan erat kaitannya dengan kehidupan budaya masyarakat setempat. Berdasarkan penelitian I Made Purna dan Kadek Dwikayana dalam jurnal Patanjala: Jurnal Penelitian Sejarah dan Budaya (2019), betutu pada awalnya digunakan sebagai hidangan persembahan kepada Ida Sang Hyang Widhi Wasa dalam tradisi keagamaan Hindu Bali. Setelah upacara selesai, makanan tersebut dapat disantap bersama. Seiring perkembangannya, betutu juga menjadi hidangan keluarga kerajaan dan masyarakat luas.\n\nNama betutu berkaitan dengan teknik pengolahan daging yang dibumbui dengan racikan rempah lengkap khas Bali, yang dikenal sebagai base genep atau bumbu genep. Ayam dibumbui hingga meresap, kemudian dimasak secara perlahan atau dipanggang menggunakan teknik tradisional. Setiap daerah dan keluarga di Bali memiliki variasi bumbu serta cara memasak tersendiri, sehingga menghasilkan cita rasa yang beragam.\n\nKini, ayam betutu telah menjadi salah satu ikon kuliner Bali yang dikenal oleh wisatawan domestik maupun mancanegara. Selain mencerminkan kekayaan rempah Nusantara, hidangan ini juga menjadi bagian dari pelestarian warisan budaya dan tradisi kuliner Bali. Betutu ditetapkan sebagai Warisan Budaya Takbenda Indonesia pada 2017, dengan persebaran yang tercatat di Kecamatan Ubud, Kabupaten Gianyar.","gambar_url":"assets/images/masakan/ayam_betutu.jpg","sumber":"Resep prototipe untuk pengembangan aplikasi; perlu kurasi dan verifikasi lokal."},{"id":"pengkang","nama":"Pengkang","daerah_asal":"Pontianak, Kalimantan Barat","kategori":"Camilan","porsi":4,"waktu_menit":60,"deskripsi":"Ketan bakar berisi ebi yang dibungkus daun pisang berbentuk kerucut, biasa disantap dengan sambal.","bahan":[{"nama":"Beras ketan","takaran":"300 g"},{"nama":"Santan","takaran":"250 ml"},{"nama":"Ebi kering","takaran":"50 g"},{"nama":"Bawang putih","takaran":"2 siung"},{"nama":"Garam","takaran":"secukupnya"},{"nama":"Daun pisang","takaran":"secukupnya"}],"langkah":["Rendam beras ketan, lalu tiriskan.","Masak ketan bersama santan dan sedikit garam hingga setengah matang.","Haluskan atau cincang ebi bersama bawang putih, lalu tumis hingga harum.","Campurkan sebagian tumisan ebi ke ketan atau letakkan sebagai isian.","Bungkus ketan dengan daun pisang membentuk kerucut dan sematkan.","Panggang di atas bara atau wajan panggang sambil dibalik hingga daun harum dan ketan matang."],"rempah_utama":["Bawang putih"],"nilai_budaya":"Pengkang merupakan kuliner ketan bakar yang dikenal di Kalimantan Barat, terutama kawasan Mempawah.","fun_fact":"Pengkang merupakan makanan tradisional khas masyarakat Melayu di Kabupaten Mempawah, Kalimantan Barat, khususnya Desa Peniti. Makanan ini memiliki kemiripan dengan lemper, tetapi dikenal dengan bentuk segitiga, isian udang ebi, serta cara penyajian yang dijepit menggunakan bilah bambu. Berdasarkan penelitian M. Alie Humaedi dan Sri Sunarti Purwaningsih dalam jurnal Patrawidya, pengkang berkembang melalui pertemuan budaya masyarakat Melayu, Bugis, Madura, dan Tionghoa di Mempawah. Perpaduan tersebut terlihat dalam penggunaan bahan, cita rasa, serta teknik pengolahan dan penyajiannya.\n\nPengkang dibuat dari beras ketan yang diisi udang ebi berbumbu, dibungkus daun pisang berbentuk segitiga, kemudian dijepit dengan bambu dan dibakar di atas bara api. Proses pembakaran menghasilkan aroma khas daun pisang dan cita rasa gurih yang menjadi ciri utamanya. Pengkang biasanya disantap bersama sambal kepah. Menurut cerita yang diwariskan masyarakat setempat, makanan ini juga praktis dibawa sebagai bekal ketika berburu, berkebun, atau berladang.\n\nSeiring waktu, pengkang berkembang menjadi ikon kuliner Kalimantan Barat yang diwariskan lintas generasi. Salah satu usaha yang turut mempertahankan tradisi ini adalah Pondok Pengkang di Peniti, yang telah berdiri sejak 1934. Pengkang juga telah ditetapkan sebagai Warisan Budaya Takbenda Indonesia pada 2021, sebagai pengakuan atas nilai budaya dan kekayaan kuliner masyarakat Mempawah.","gambar_url":"assets/images/masakan/pengkang.jpg","sumber":"Resep prototipe untuk pengembangan aplikasi; takaran dan langkah perlu diverifikasi dengan tradisi lokal."},{"id":"ikan-sabu-sabu","nama":"Ikan Sabu-Sabu","daerah_asal":"Indonesia","kategori":"Ikan","porsi":null,"waktu_menit":null,"deskripsi":"Olahan ikan segar bercita rasa gurih khas Nusantara.","bahan":[],"langkah":[],"rempah_utama":[],"nilai_budaya":"","gambar_url":"","sumber":"Data awal; resep belum tersedia."},{"id":"bubur-pedas","nama":"Bubur Pedas","daerah_asal":"Sambas, Kalimantan Barat","kategori":"Bubur","porsi":4,"waktu_menit":75,"deskripsi":"Bubur sayur berempah khas Melayu Sambas dengan aneka dedaunan.","bahan":[{"nama":"Beras","takaran":"150 g"},{"nama":"Air atau kaldu","takaran":"1,5 liter"},{"nama":"Kangkung","takaran":"1 ikat"},{"nama":"Daun pakis atau sayuran lokal","takaran":"1 ikat"},{"nama":"Kacang tanah sangrai","takaran":"50 g"},{"nama":"Kelapa parut sangrai","takaran":"50 g"},{"nama":"Bawang merah","takaran":"5 butir"},{"nama":"Bawang putih","takaran":"3 siung"},{"nama":"Cabai","takaran":"sesuai selera"},{"nama":"Serai","takaran":"1 batang"},{"nama":"Garam","takaran":"secukupnya"}],"langkah":["Sangrai beras hingga agak kecokelatan, lalu tumbuk kasar jika diinginkan.","Haluskan bawang merah, bawang putih, dan cabai.","Didihkan air atau kaldu, masukkan beras dan serai, lalu masak sambil diaduk.","Tambahkan bumbu halus dan sayuran secara bertahap hingga beras menjadi bubur.","Masukkan kacang dan kelapa sangrai, lalu bumbui dengan garam.","Masak hingga tekstur sesuai selera dan sajikan hangat dengan pelengkap."],"rempah_utama":["Serai","Bawang merah","Bawang putih","Cabai"],"nilai_budaya":"Bubur pedas dikenal dalam tradisi Melayu Sambas dan sering disajikan dalam kegiatan kebersamaan serta bulan Ramadan.","fun_fact":"Bubur pedas atau bubbor paddas merupakan makanan tradisional masyarakat Melayu Sambas, Kalimantan Barat, yang diwariskan secara turun-temurun. Hidangan ini telah lama menjadi bagian dari identitas budaya masyarakat Sambas dan menurut sejumlah sumber kuliner, dahulu juga disajikan dalam lingkungan kerajaan serta acara adat. Namun, catatan sejarah yang memastikan kapan dan siapa pencipta pertama bubur pedas masih terbatas.\n\nBubur pedas dibuat dari beras yang ditumbuk, kemudian disangrai dan dimasak bersama berbagai rempah serta sayuran, seperti daun kesum, daun kunyit, pakis, dan kangkung. Meskipun bernama bubur pedas, rasa khasnya berasal dari perpaduan rempah yang gurih dan aromatik, bukan semata-mata dari cabai. Daun kesum menjadi salah satu bahan penting yang memberikan aroma khas pada hidangan ini.\n\nSeiring waktu, bubur pedas menyebar ke berbagai daerah di Kalimantan Barat, termasuk Pontianak dan Singkawang. Hidangan ini juga sering dijumpai selama bulan Ramadan sebagai menu berbuka puasa. Selain menjadi makanan sehari-hari, bubur pedas berperan dalam menjaga warisan kuliner dan memperkenalkan budaya Melayu Sambas kepada generasi muda serta masyarakat luas.","gambar_url":"assets/images/masakan/bubur_pedas.jpg","sumber":"Resep prototipe untuk pengembangan aplikasi; takaran dan langkah perlu diverifikasi dengan tradisi lokal."},{"id":"rawon","nama":"Rawon","daerah_asal":"Jawa Timur","kategori":"Sup","porsi":4,"waktu_menit":120,"deskripsi":"Sup daging sapi berkuah hitam pekat dari kluwek dengan aroma rempah yang kuat.","bahan":[{"nama":"Daging sapi","takaran":"700 g"},{"nama":"Air","takaran":"2 liter"},{"nama":"Kluwek matang","takaran":"4–5 buah, ambil isinya"},{"nama":"Bawang merah","takaran":"7 butir"},{"nama":"Bawang putih","takaran":"4 siung"},{"nama":"Kemiri","takaran":"3 butir"},{"nama":"Ketumbar","takaran":"1 sdt"},{"nama":"Jahe","takaran":"2 cm"},{"nama":"Lengkuas","takaran":"3 cm"},{"nama":"Serai","takaran":"2 batang"},{"nama":"Daun jeruk","takaran":"4 lembar"},{"nama":"Garam","takaran":"secukupnya"}],"langkah":["Rebus daging hingga cukup empuk, angkat dan potong-potong; simpan kaldunya.","Pastikan isi kluwek berwarna dan beraroma baik; jangan gunakan kluwek yang pahit atau berbau tidak normal.","Haluskan kluwek bersama bawang merah, bawang putih, kemiri, ketumbar, dan jahe.","Tumis bumbu halus hingga harum, lalu masukkan lengkuas, serai, dan daun jeruk.","Masukkan tumisan ke dalam kaldu, tambahkan daging, lalu masak dengan api kecil hingga bumbu meresap.","Bumbui dengan garam dan sajikan bersama nasi serta pelengkap sesuai selera."],"rempah_utama":["Kluwek","Kemiri","Ketumbar","Jahe","Lengkuas","Serai","Daun jeruk"],"nilai_budaya":"Rawon merupakan kuliner Jawa Timur yang dikenal melalui kuah hitam dari kluwek.","fun_fact":"Rawon merupakan makanan tradisional khas Jawa Timur berupa sup daging sapi dengan kuah berwarna hitam pekat. Berdasarkan penelitian Erni Sofia Murtini dan Befrika S. Murdianti yang diterbitkan dalam Journal of Ethnic Foods pada 2024, rawon telah dikenal sejak masa Jawa kuno dan kemungkinan awalnya merupakan hidangan kalangan kerajaan. Salah satu catatan kuliner yang berkaitan dengan rawon ditemukan dalam naskah Kakawin Bhomakaya dari masa Kerajaan Kadiri, yang menyebut istilah rarawwan. Namun, asal-usul pasti makanan ini masih belum sepenuhnya diketahui.\n\nKeunikan rawon terletak pada penggunaan kluwek atau keluak (Pangium edule) yang memberikan warna hitam sekaligus cita rasa gurih khas pada kuahnya. Daging sapi dimasak bersama berbagai rempah, seperti bawang merah, bawang putih, lengkuas, kunyit, jahe, dan ketumbar. Rawon biasanya disajikan bersama nasi putih, tauge pendek, sambal, telur asin, serta kerupuk atau emping.\n\nSeiring waktu, rawon menyebar luas dan menjadi salah satu ikon kuliner Jawa Timur, terutama di Surabaya dan Pasuruan. Hidangan ini tidak lagi terbatas pada kalangan kerajaan, tetapi dapat dinikmati oleh masyarakat dari berbagai lapisan. Selain menjadi makanan sehari-hari, rawon juga kerap disajikan dalam acara keluarga dan perayaan, mencerminkan kekayaan tradisi kuliner Jawa yang diwariskan dari generasi ke generasi.","gambar_url":"assets/images/masakan/rawon.jpg","sumber":"Resep prototipe untuk pengembangan aplikasi; takaran dan langkah perlu diverifikasi dengan tradisi lokal."},{"id":"sate-padang","nama":"Sate Padang","daerah_asal":"Padang, Sumatera Barat","kategori":"Sate","porsi":4,"waktu_menit":90,"deskripsi":"Sate daging sapi dengan kuah kental berempah khas Minang.","bahan":[{"nama":"Daging sapi","takaran":"500 g"},{"nama":"Air atau kaldu","takaran":"1 liter"},{"nama":"Bawang merah","takaran":"8 butir"},{"nama":"Bawang putih","takaran":"4 siung"},{"nama":"Cabai merah","takaran":"sesuai selera"},{"nama":"Jahe","takaran":"2 cm"},{"nama":"Lengkuas","takaran":"3 cm"},{"nama":"Kunyit","takaran":"2 cm"},{"nama":"Ketumbar","takaran":"1 sdt"},{"nama":"Jinten","takaran":"1/2 sdt"},{"nama":"Tepung beras","takaran":"2 sdm, larutkan"},{"nama":"Garam","takaran":"secukupnya"}],"langkah":["Rebus daging hingga setengah empuk, lalu potong sesuai ukuran sate dan simpan kaldunya.","Haluskan bawang merah, bawang putih, cabai, jahe, lengkuas, kunyit, ketumbar, dan jinten.","Tumis bumbu hingga harum, kemudian masukkan ke dalam kaldu.","Masukkan potongan daging dan masak hingga empuk serta bumbu meresap.","Tusukkan daging pada tusuk sate dan panggang sebentar hingga beraroma.","Kentalkan kuah dengan larutan tepung beras sambil diaduk, lalu sajikan sebagai saus sate."],"rempah_utama":["Jahe","Lengkuas","Kunyit","Ketumbar","Jinten"],"nilai_budaya":"Sate Padang mencerminkan ragam kuliner Minangkabau dengan variasi kuah dan racikan rempah antardaerah.","fun_fact":"Sate Padang merupakan makanan tradisional khas Sumatera Barat yang berasal dari tradisi kuliner masyarakat Minangkabau. Hidangan ini dipercaya berasal dari Padang Panjang, kemudian menyebar ke daerah lain, termasuk Pariaman, melalui perjalanan para pemuda dan peziarah yang menuntut ilmu agama. Dalam perkembangannya, resep sate mengalami penyesuaian bumbu sesuai dengan selera masyarakat setempat. Meskipun sejarahnya telah lama dikenal secara turun-temurun, belum ditemukan catatan resmi yang memastikan kapan sate Padang pertama kali dibuat dan siapa penciptanya.\n\nSate Padang umumnya dibuat dari potongan daging sapi, lidah, atau jeroan yang dibumbui, direbus hingga empuk, ditusuk, kemudian dibakar. Keunikannya terletak pada kuah kental berbumbu rempah, seperti kunyit, ketumbar, serai, lengkuas, jahe, dan cabai. Sate ini memiliki beberapa variasi daerah, antara lain sate Padang Panjang dengan kuah kekuningan dan sate Pariaman dengan kuah kemerahan yang cenderung lebih pedas.\n\nSeiring waktu, sate Padang berkembang menjadi salah satu ikon kuliner Sumatera Barat dan menyebar ke berbagai wilayah Indonesia melalui perantauan masyarakat Minangkabau. Hidangan ini biasanya disajikan bersama ketupat, taburan bawang goreng, dan kuah rempah yang khas. Selain menjadi makanan favorit masyarakat, keberagaman resep sate Padang mencerminkan kekayaan tradisi kuliner Minangkabau yang terus diwariskan dan dilestarikan hingga kini.","gambar_url":"assets/images/masakan/sate_padang.jpg","sumber":"Resep prototipe untuk pengembangan aplikasi; takaran dan langkah perlu diverifikasi dengan tradisi lokal."},{"id":"sate","nama":"Sate","daerah_asal":"Berbagai daerah","kategori":"Sate","porsi":null,"waktu_menit":null,"deskripsi":"Potongan daging ditusuk dan dibakar, disajikan dengan bumbu kacang atau kecap.","bahan":[],"langkah":[],"rempah_utama":[],"nilai_budaya":"","gambar_url":"","sumber":"Data awal; resep belum tersedia."},{"id":"ayam-taliwang","nama":"Ayam Taliwang","daerah_asal":"Lombok, Nusa Tenggara Barat","kategori":"Unggas","porsi":4,"waktu_menit":60,"deskripsi":"Ayam bakar berbumbu pedas khas Lombok.","bahan":[{"nama":"Ayam","takaran":"1 ekor kecil atau 4 potong"},{"nama":"Bawang merah","takaran":"8 butir"},{"nama":"Bawang putih","takaran":"4 siung"},{"nama":"Cabai merah","takaran":"8–12 buah, sesuai selera"},{"nama":"Tomat","takaran":"1 buah"},{"nama":"Terasi","takaran":"1 sdt"},{"nama":"Kencur","takaran":"2 cm"},{"nama":"Gula merah","takaran":"1 sdt"},{"nama":"Garam","takaran":"secukupnya"},{"nama":"Minyak","takaran":"2 sdm"}],"langkah":["Bersihkan ayam dan buat beberapa sayatan agar bumbu mudah meresap.","Haluskan bawang merah, bawang putih, cabai, tomat, terasi, dan kencur.","Tumis bumbu dengan minyak hingga harum, lalu tambahkan gula merah dan garam.","Lumuri ayam dengan bumbu dan diamkan selama 15–30 menit.","Panggang ayam sambil diolesi sisa bumbu hingga matang sempurna dan permukaannya sedikit kecokelatan.","Sajikan hangat dengan plecing kangkung atau pelengkap sesuai selera."],"rempah_utama":["Cabai","Kencur","Bawang merah","Bawang putih"],"nilai_budaya":"Ayam Taliwang merupakan hidangan khas Lombok yang dikenal dengan bumbu cabai dan teknik pemanggangan.","fun_fact":"Menurut salah satu versi sejarah yang dibahas dalam penelitian, kemunculan Ayam Taliwang dikaitkan dengan konflik antara Kerajaan Selaparang di Lombok dan Kerajaan Karangasem dari Bali. Pasukan dari Taliwang datang ke Lombok dalam konteks konflik tersebut, kemudian terjadi interaksi budaya yang turut memengaruhi perkembangan hidangan ayam berbumbu. Namun, rincian kronologi asal-usulnya memiliki beberapa versi, sehingga cerita ini sebaiknya dipahami sebagai riwayat yang berkembang dalam tradisi sejarah kuliner, bukan sebagai fakta tunggal yang sepenuhnya pasti.\n\nAyam Taliwang umumnya dibuat menggunakan ayam kampung muda yang dibakar atau dipanggang dengan bumbu bercita rasa pedas dan gurih, seperti cabai merah, bawang putih, bawang merah, tomat, terasi, dan kencur. Sejak sekitar 1960-an, hidangan ini mulai berkembang sebagai usaha kuliner dan semakin populer pada 1970-an. Kini, Ayam Taliwang menjadi salah satu ikon kuliner Lombok yang kerap disajikan bersama nasi putih dan plecing kangkung.","gambar_url":"assets/images/masakan/ayam_taliwang.jpg","sumber":"Resep prototipe untuk pengembangan aplikasi; takaran dan langkah perlu diverifikasi dengan tradisi lokal."},{"id":"mie-aceh","nama":"Mie Aceh","daerah_asal":"Aceh","kategori":"Mie","porsi":4,"waktu_menit":45,"deskripsi":"Mie berbumbu rempah pekat khas Aceh, tersedia versi kuah maupun goreng.","bahan":[{"nama":"Mi kuning tebal","takaran":"500 g"},{"nama":"Daging sapi atau udang","takaran":"250 g"},{"nama":"Bawang merah","takaran":"6 butir"},{"nama":"Bawang putih","takaran":"4 siung"},{"nama":"Cabai merah","takaran":"sesuai selera"},{"nama":"Jahe","takaran":"2 cm"},{"nama":"Kapulaga","takaran":"2 butir"},{"nama":"Jintan","takaran":"1/2 sdt"},{"nama":"Ketumbar","takaran":"1 sdt"},{"nama":"Tomat","takaran":"1 buah"},{"nama":"Kaldu","takaran":"500 ml"},{"nama":"Kol dan tauge","takaran":"secukupnya"}],"langkah":["Haluskan bawang merah, bawang putih, cabai, jahe, kapulaga, jintan, dan ketumbar.","Tumis bumbu hingga harum, lalu masukkan daging atau udang dan masak hingga berubah warna.","Tambahkan tomat dan kaldu; didihkan hingga bahan utama matang.","Masukkan mi dan sayuran, lalu aduk hingga bumbu meresap.","Sesuaikan kekentalan kuah menurut pilihan mi goreng, tumis, atau kuah.","Sajikan dengan acar, jeruk nipis, atau pelengkap sesuai selera."],"rempah_utama":["Jahe","Kapulaga","Jintan","Ketumbar","Cabai"],"nilai_budaya":"Mie Aceh memperlihatkan pengaruh perdagangan dan perpaduan rempah dalam tradisi kuliner Aceh.","fun_fact":"Mi Aceh merupakan makanan tradisional khas Provinsi Aceh yang berkembang melalui pertemuan berbagai budaya akibat posisi Aceh sebagai jalur perdagangan penting di kawasan Samudra Hindia. Sejarah kulinernya berkaitan dengan interaksi masyarakat setempat dengan pedagang dari Tiongkok, India, dan kawasan Arab. Pengaruh kuliner Tiongkok terlihat pada penggunaan mi, sedangkan pengaruh masakan India tampak pada penggunaan bumbu kari dan rempah-rempah yang kuat. Meski demikian, waktu pasti kemunculan Mi Aceh dan pencipta pertamanya belum terdokumentasi secara jelas.\n\nMi Aceh memiliki ciri khas berupa mi kuning yang tebal dan kenyal, dimasak dengan racikan rempah seperti cabai, kunyit, jintan, kapulaga, dan lada. Hidangan ini tersedia dalam beberapa variasi, yaitu mi goreng, mi tumis atau goreng basah, serta mi kuah. Isiannya dapat berupa daging sapi, kambing, udang, cumi-cumi, atau kepiting, kemudian disajikan bersama acar mentimun, emping, dan jeruk nipis.\n\nSeiring waktu, Mi Aceh berkembang menjadi salah satu ikon kuliner Aceh dan menyebar ke berbagai kota di Indonesia. Selain menjadi hidangan sehari-hari, makanan ini mencerminkan keterbukaan masyarakat Aceh terhadap pengaruh budaya luar yang kemudian diolah menjadi identitas kuliner lokal. Penelitian dalam jurnal Al-Ukhwah: Jurnal Pengembangan Masyarakat Islam juga menyoroti nilai kebersamaan, penghormatan kepada tamu, dan pewarisan pengetahuan rempah dalam tradisi Mi Aceh.","gambar_url":"assets/images/masakan/mie_aceh.jpg","sumber":"Resep prototipe untuk pengembangan aplikasi; takaran dan langkah perlu diverifikasi dengan tradisi lokal."},{"id":"pempek","nama":"Pempek","daerah_asal":"Palembang, Sumatera Selatan","kategori":"Camilan","porsi":4,"waktu_menit":60,"deskripsi":"Olahan ikan dan sagu yang disajikan dengan kuah cuko asam-pedas-manis.","bahan":[{"nama":"Daging ikan giling","takaran":"500 g"},{"nama":"Tepung sagu atau tapioka","takaran":"350–450 g"},{"nama":"Air es","takaran":"150 ml"},{"nama":"Garam","takaran":"1 sdt"},{"nama":"Bawang putih","takaran":"2 siung, haluskan"},{"nama":"Gula merah","takaran":"150 g"},{"nama":"Air untuk cuko","takaran":"400 ml"},{"nama":"Asam jawa","takaran":"2 sdm"},{"nama":"Cabai rawit","takaran":"sesuai selera"}],"langkah":["Campur ikan giling, air es, garam, dan bawang putih hingga rata.","Tambahkan tepung sagu sedikit demi sedikit; aduk seperlunya hingga adonan dapat dibentuk.","Bentuk adonan sesuai jenis pempek yang diinginkan.","Rebus pempek dalam air mendidih hingga mengapung dan matang, lalu tiriskan.","Untuk cuko, rebus air, gula merah, asam jawa, bawang putih, dan cabai; saring setelah rasanya menyatu.","Pempek dapat digoreng sebelum disajikan bersama cuko."],"rempah_utama":["Bawang putih","Asam jawa","Cabai"],"nilai_budaya":"Pempek merupakan kuliner khas Palembang yang berkaitan erat dengan tradisi masyarakat sungai dan perikanan.","fun_fact":"Pempek merupakan makanan tradisional khas Palembang, Sumatera Selatan, yang dibuat dari campuran daging ikan dan tepung sagu. Menurut penelitian yang diterbitkan dalam Journal of Ethnic Foods pada 2023, pempek berkembang berkat ketersediaan ikan dan sagu di wilayah Sumatera Selatan serta pengaruh interaksi budaya Melayu dan Tionghoa. Meskipun terdapat teori yang menghubungkan pempek dengan masa Kerajaan Sriwijaya pada abad ke-7, bukti sejarah mengenai kemunculan pempek dalam bentuk yang dikenal sekarang belum dapat dipastikan secara mutlak.\n\nPada awalnya, pempek dikenal dengan nama kelesan, yaitu olahan ikan yang dihaluskan, dicampur tepung sagu, garam, dan air, kemudian dibentuk serta direbus. Menurut salah satu cerita asal-usul yang populer, nama pempek berkaitan dengan sebutan Apek atau Pek untuk pedagang keturunan Tionghoa yang menjual makanan tersebut pada awal abad ke-20. Pempek biasanya disajikan bersama kuah cuko yang terbuat dari gula merah, cabai, bawang putih, dan asam, sehingga menghasilkan perpaduan rasa manis, asam, dan pedas.\n\nSeiring waktu, pempek berkembang menjadi ikon kuliner Palembang dan menyebar ke berbagai daerah di Indonesia. Beragam jenisnya, seperti pempek kapal selam, lenjer, adaan, dan kulit, menunjukkan perkembangan kreativitas masyarakat dalam mengolah bahan pangan lokal. Selain menjadi makanan sehari-hari dan oleh-oleh khas, pempek juga berperan sebagai simbol identitas budaya masyarakat Palembang serta mendukung perekonomian pelaku usaha kuliner setempat.","gambar_url":"assets/images/masakan/pempek.jpg","sumber":"Resep prototipe untuk pengembangan aplikasi; takaran dan langkah perlu diverifikasi dengan tradisi lokal."},{"id":"gudeg","nama":"Gudeg","daerah_asal":"Yogyakarta","kategori":"Sayur","porsi":4,"waktu_menit":180,"deskripsi":"Nangka muda yang dimasak santan hingga manis gurih khas Yogyakarta.","bahan":[{"nama":"Nangka muda","takaran":"1 kg"},{"nama":"Santan","takaran":"1 liter"},{"nama":"Bawang merah","takaran":"6 butir"},{"nama":"Bawang putih","takaran":"4 siung"},{"nama":"Kemiri","takaran":"3 butir"},{"nama":"Ketumbar","takaran":"1 sdt"},{"nama":"Daun salam","takaran":"4 lembar"},{"nama":"Lengkuas","takaran":"3 cm"},{"nama":"Gula merah","takaran":"100 g atau sesuai selera"},{"nama":"Garam","takaran":"secukupnya"}],"langkah":["Rebus nangka muda hingga agak empuk, lalu tiriskan.","Haluskan bawang merah, bawang putih, kemiri, dan ketumbar.","Susun nangka, bumbu halus, daun salam, lengkuas, gula merah, dan santan dalam panci.","Masak dengan api kecil hingga nangka empuk dan bumbu meresap; aduk sesekali agar tidak gosong.","Masak lebih lama bila ingin warna lebih gelap dan rasa lebih pekat.","Sajikan dengan nasi dan pelengkap sesuai tradisi setempat."],"rempah_utama":["Kemiri","Ketumbar","Daun salam","Lengkuas"],"nilai_budaya":"Gudeg dikenal sebagai salah satu ikon kuliner Yogyakarta dan memiliki beragam variasi resep keluarga.","fun_fact":"Gudeg merupakan makanan tradisional khas Daerah Istimewa Yogyakarta yang berbahan dasar nangka muda dan dimasak bersama santan serta berbagai rempah. Asal-usul gudeg sering dikaitkan dengan sejarah perkembangan wilayah Mataram Islam pada abad ke-16, ketika kawasan hutan di sekitar Kotagede dibuka untuk pembangunan permukiman. Nangka muda yang tersedia melimpah kemudian diolah menjadi makanan dengan cara dimasak dalam waktu lama. Meski kisah ini populer dalam penuturan sejarah kuliner, bukti tertulis yang memastikan waktu penciptaan gudeg secara tepat masih terbatas.\n\nNama gudeg diyakini berasal dari kata bahasa Jawa ngudeg atau hangudeg, yang berarti mengaduk, merujuk pada proses mengaduk nangka muda selama dimasak. Gudeg diolah dengan santan, gula merah, dan aneka rempah, terkadang ditambah daun jati untuk menghasilkan warna cokelat kemerahan. Hidangan ini biasanya disajikan bersama nasi, ayam, telur, areh, dan sambal goreng krecek. Seiring waktu, gudeg berkembang dari makanan masyarakat menjadi ikon kuliner Yogyakarta dan ditetapkan sebagai Warisan Budaya Takbenda Indonesia pada 2015.","gambar_url":"assets/images/masakan/gudeg.jpg","sumber":"Resep prototipe untuk pengembangan aplikasi; takaran dan langkah perlu diverifikasi dengan tradisi lokal."},{"id":"nasi-jalang","nama":"Nasi Jalang","daerah_asal":"Meulaboh, Aceh","kategori":"Nasi","porsi":null,"waktu_menit":null,"deskripsi":"Nasi dengan beragam lauk berempah khas Aceh Barat.","bahan":[],"langkah":[],"rempah_utama":[],"nilai_budaya":"","gambar_url":"","sumber":"Data awal; resep belum tersedia."},{"id":"nasi-liwet","nama":"Nasi Liwet","daerah_asal":"Solo, Jawa Tengah","kategori":"Nasi","porsi":4,"waktu_menit":45,"deskripsi":"Nasi gurih bersantan dengan aneka lauk, khas Surakarta.","bahan":[{"nama":"Beras","takaran":"400 g"},{"nama":"Santan atau kaldu","takaran":"sesuai kebutuhan memasak nasi"},{"nama":"Bawang merah","takaran":"4 butir"},{"nama":"Bawang putih","takaran":"2 siung"},{"nama":"Serai","takaran":"1 batang"},{"nama":"Daun salam","takaran":"2 lembar"},{"nama":"Daun pandan","takaran":"1 lembar, opsional"},{"nama":"Garam","takaran":"secukupnya"}],"langkah":["Cuci beras hingga bersih.","Iris bawang merah dan bawang putih, lalu tumis hingga harum.","Masukkan beras, serai, daun salam, dan daun pandan ke dalam panci atau penanak nasi.","Tambahkan santan atau kaldu secukupnya sesuai takaran beras, lalu bumbui dengan garam.","Masak hingga nasi matang dan cairan terserap.","Aduk ringan dan sajikan dengan lauk serta sayuran pelengkap."],"rempah_utama":["Serai","Daun salam"],"nilai_budaya":"Nasi liwet dikenal dalam tradisi kuliner Surakarta dan lazim disajikan bersama beragam lauk.","fun_fact":"Nasi liwet merupakan hidangan tradisional Indonesia yang dikenal dalam dua variasi populer, yaitu nasi liwet Solo dari Jawa Tengah dan nasi liwet Sunda dari Jawa Barat. Menurut penelitian yang diterbitkan dalam Destinesia: Jurnal Hospitaliti dan Pariwisata pada 2022, nasi liwet Solo berkaitan dengan tradisi kuliner masyarakat Jawa dan lingkungan keraton Surakarta. Teknik memasak nasi liwet juga tercatat dalam naskah Jawa Serat Centhini yang ditulis pada awal abad ke-19. Namun, asal-usul pasti hidangan ini belum diketahui secara lengkap.\n\nNasi liwet Solo dibuat dari beras yang dimasak dengan santan dan rempah sehingga menghasilkan nasi gurih, kemudian disajikan bersama sayur labu siam, ayam suwir, telur, dan areh atau santan kental. Sementara itu, nasi liwet Sunda umumnya dimasak tanpa santan, menggunakan bumbu seperti bawang, serai, dan daun salam, serta sering dilengkapi ikan asin, sambal, dan lalapan. Perbedaan tersebut menunjukkan bagaimana hidangan bernama sama berkembang sesuai tradisi dan bahan pangan setiap daerah.\n\nDalam perkembangannya, nasi liwet menjadi bagian dari tradisi makan bersama, syukuran, dan kehidupan sehari-hari masyarakat. Nasi liwet Solo juga dikenal melalui penjual dari Desa Menuran, Kabupaten Sukoharjo, yang kemudian memopulerkannya di Kota Solo. Kini, nasi liwet menjadi salah satu kekayaan kuliner Nusantara yang mencerminkan nilai kebersamaan, rasa syukur, dan warisan budaya masyarakat Indonesia.","gambar_url":"assets/images/masakan/nasi_liwet.jpeg","sumber":"Resep prototipe untuk pengembangan aplikasi; takaran dan langkah perlu diverifikasi dengan tradisi lokal."},{"id":"soto-betawi","nama":"Soto Betawi","daerah_asal":"Jakarta","kategori":"Sup","porsi":null,"waktu_menit":null,"deskripsi":"Soto bersantan atau susu dengan potongan daging dan jeroan sapi.","bahan":[],"langkah":[],"rempah_utama":[],"nilai_budaya":"","fun_fact":"Soto Betawi merupakan makanan tradisional khas masyarakat Betawi dari Jakarta. Meskipun hidangan soto telah berkembang di Nusantara melalui percampuran berbagai budaya kuliner, nama “Soto Betawi” baru populer sekitar 1977–1978. Menurut catatan sejarah kuliner yang dipublikasikan oleh Radio Republik Indonesia (RRI) dan katalog Warisan Budaya Takbenda Indonesia, nama tersebut pertama kali dipopulerkan oleh penjual soto bernama Lie Boen Po, yang berjualan di kawasan THR Lokasari, dahulu dikenal sebagai Prinsen Park. Sebelumnya, penjual soto di Jakarta sering menggunakan nama penjual atau jenis bagian daging sebagai nama dagangan mereka.\n\nCiri khas Soto Betawi terletak pada kuahnya yang gurih dan kaya rasa, biasanya dibuat dari campuran santan dan susu, dengan isian daging sapi serta jeroan seperti babat dan paru. Hidangan ini umumnya disajikan bersama tomat, kentang, daun bawang, emping, dan bawang goreng. Perpaduan bahan tersebut menghasilkan kuah yang lebih kental dan beraroma dibandingkan beberapa jenis soto lainnya.\n\nSeiring waktu, Soto Betawi berkembang dari hidangan yang dijual pedagang kaki lima menjadi salah satu ikon kuliner Jakarta yang dikenal luas di berbagai daerah Indonesia. Keberadaan usaha legendaris seperti Soto Betawi Haji Maruf juga memperlihatkan bagaimana kuliner ini bertahan menghadapi perubahan sosial dan perkembangan kota. Pada 2016, Soto Betawi ditetapkan sebagai Warisan Budaya Takbenda Indonesia oleh pemerintah, sebagai bagian dari upaya pengakuan dan pelestarian budaya kuliner Betawi.","gambar_url":"","sumber":"Data awal; resep belum tersedia."},{"id":"tahu-tek","nama":"Tahu Tek","daerah_asal":"Surabaya, Jawa Timur","kategori":"Camilan","porsi":null,"waktu_menit":null,"deskripsi":"Tahu goreng dan lontong yang disiram bumbu petis kacang.","bahan":[],"langkah":[],"rempah_utama":[],"nilai_budaya":"","gambar_url":"","sumber":"Data awal; resep belum tersedia."},{"id":"pecel-madiun","nama":"Pecel Madiun","daerah_asal":"Madiun, Jawa Timur","kategori":"Sayur","porsi":null,"waktu_menit":null,"deskripsi":"Aneka sayuran rebus yang disiram sambal kacang khas Madiun.","bahan":[],"langkah":[],"rempah_utama":[],"nilai_budaya":"","gambar_url":"","sumber":"Data awal; resep belum tersedia."},{"id":"sate-lilit","nama":"Sate Lilit","daerah_asal":"Bali","kategori":"Sate","porsi":null,"waktu_menit":null,"deskripsi":"Sate daging cincang berbumbu yang dililitkan pada batang serai atau bambu.","bahan":[],"langkah":[],"rempah_utama":[],"nilai_budaya":"","gambar_url":"","sumber":"Data awal; resep belum tersedia."},{"id":"coto-makassar","nama":"Coto Makassar","daerah_asal":"Makassar, Sulawesi Selatan","kategori":"Sup","porsi":4,"waktu_menit":150,"deskripsi":"Sup daging dan jeroan sapi berempah khas Makassar.","bahan":[{"nama":"Daging sapi dan jeroan sesuai pilihan","takaran":"700 g"},{"nama":"Air","takaran":"2 liter"},{"nama":"Kacang tanah sangrai","takaran":"100 g"},{"nama":"Bawang merah","takaran":"8 butir"},{"nama":"Bawang putih","takaran":"5 siung"},{"nama":"Ketumbar","takaran":"1 sdm"},{"nama":"Jintan","takaran":"1/2 sdt"},{"nama":"Jahe","takaran":"3 cm"},{"nama":"Lengkuas","takaran":"3 cm"},{"nama":"Serai","takaran":"2 batang"},{"nama":"Daun salam","takaran":"2 lembar"},{"nama":"Garam","takaran":"secukupnya"}],"langkah":["Rebus daging dan jeroan secara terpisah bila diperlukan hingga matang; potong sesuai selera dan simpan kaldunya.","Haluskan kacang tanah sangrai bersama bawang merah, bawang putih, ketumbar, jintan, dan jahe.","Tumis bumbu halus hingga harum, lalu masukkan lengkuas, serai, dan daun salam.","Masukkan bumbu ke dalam kaldu, tambahkan daging, lalu masak perlahan hingga rasa menyatu.","Bumbui dengan garam dan koreksi rasa.","Sajikan dengan ketupat atau burasa serta sambal sesuai selera."],"rempah_utama":["Ketumbar","Jintan","Jahe","Lengkuas","Serai","Daun salam"],"nilai_budaya":"Coto Makassar merupakan kuliner berkuah khas Sulawesi Selatan yang menggunakan racikan rempah dan kacang.","fun_fact":"Coto Makassar merupakan makanan tradisional khas Makassar, Sulawesi Selatan, yang diperkirakan telah ada sejak abad ke-16 pada masa Kerajaan Gowa, ketika pusat kerajaan berada di Somba Opu. Menurut sejumlah sumber sejarah kuliner, hidangan ini awalnya berkaitan dengan lingkungan kerajaan dan kemudian berkembang menjadi makanan yang dinikmati oleh berbagai kalangan masyarakat. Salah satu kisah yang berkembang menceritakan seorang juru masak bernama Toak yang mengolah daging dan jeroan dengan aneka rempah. Namun, kisah tersebut merupakan versi tradisi sejarah yang belum sepenuhnya dapat dipastikan.\n\nCoto Makassar dibuat dari daging sapi dan jeroan yang direbus hingga empuk dalam kuah kaya rempah, seperti ketumbar, jintan, lengkuas, jahe, serai, dan bawang putih. Kacang tanah yang dihaluskan memberikan tekstur kuah yang khas, sedangkan sambal tauco yang disajikan sebagai pelengkap menunjukkan kemungkinan adanya pengaruh kuliner Tionghoa dalam perkembangannya. Hidangan ini biasanya disantap bersama burasa atau ketupat.\n\nSeiring waktu, Coto Makassar berkembang menjadi ikon kuliner Sulawesi Selatan yang diwariskan secara turun-temurun dan dikenal di berbagai daerah di Indonesia. Hidangan ini tidak hanya mencerminkan kekayaan rempah Nusantara, tetapi juga sejarah interaksi budaya dan perdagangan di Makassar. Pemerintah Indonesia menetapkan Coto Makassar sebagai Warisan Budaya Takbenda pada 2015 sebagai bentuk pengakuan terhadap nilai budaya kuliner tersebut.","gambar_url":"assets/images/masakan/coto_makassar.jpg","sumber":"Resep prototipe untuk pengembangan aplikasi; takaran dan langkah perlu diverifikasi dengan tradisi lokal."},{"id":"konro","nama":"Konro","daerah_asal":"Makassar, Sulawesi Selatan","kategori":"Sup","porsi":null,"waktu_menit":null,"deskripsi":"Sup atau iga bakar berkuah rempah khas Bugis-Makassar.","bahan":[],"langkah":[],"rempah_utama":[],"nilai_budaya":"","gambar_url":"","sumber":"Data awal; resep belum tersedia."},{"id":"ikan-bakar-rica-rica","nama":"Ikan Bakar Rica-Rica","daerah_asal":"Manado, Sulawesi Utara","kategori":"Ikan","porsi":null,"waktu_menit":null,"deskripsi":"Ikan bakar yang dilumuri sambal rica-rica pedas khas Manado.","bahan":[],"langkah":[],"rempah_utama":[],"nilai_budaya":"","gambar_url":"","sumber":"Data awal; resep belum tersedia."},{"id":"soto-banjar","nama":"Soto Banjar","daerah_asal":"Banjarmasin, Kalimantan Selatan","kategori":"Sup","porsi":4,"waktu_menit":60,"deskripsi":"Soto ayam beraroma kayu manis dan cengkeh khas Banjar.","bahan":[{"nama":"Ayam","takaran":"700 g"},{"nama":"Air","takaran":"1,5 liter"},{"nama":"Bawang merah","takaran":"6 butir"},{"nama":"Bawang putih","takaran":"4 siung"},{"nama":"Jahe","takaran":"2 cm"},{"nama":"Kayu manis","takaran":"1 batang kecil"},{"nama":"Cengkeh","takaran":"3 butir"},{"nama":"Kapulaga","takaran":"2 butir"},{"nama":"Pala","takaran":"sejumput"},{"nama":"Garam dan merica","takaran":"secukupnya"}],"langkah":["Rebus ayam hingga matang, angkat dan suwir dagingnya; sisihkan kaldu.","Haluskan bawang merah, bawang putih, dan jahe.","Tumis bumbu halus hingga harum.","Masukkan tumisan ke kaldu bersama kayu manis, cengkeh, kapulaga, dan pala.","Didihkan perlahan sekitar 15–20 menit, lalu bumbui dengan garam dan merica.","Sajikan bersama suwiran ayam dan pelengkap sesuai selera."],"rempah_utama":["Jahe","Kayu manis","Cengkeh","Kapulaga","Pala"],"nilai_budaya":"Soto Banjar merupakan hidangan khas masyarakat Banjar dengan aroma rempah yang khas.","fun_fact":"Soto Banjar merupakan makanan tradisional khas masyarakat suku Banjar yang berasal dari Banjarmasin, Kalimantan Selatan. Asal-usulnya belum diketahui secara pasti, tetapi sejumlah kajian sejarah kuliner mengaitkan perkembangannya dengan interaksi masyarakat Banjar dan pedagang Tionghoa yang datang ke Nusantara sejak berabad-abad lalu. Pengaruh tersebut diduga berkaitan dengan hidangan berkuah berbumbu yang dikenal sebagai jao to, kemudian beradaptasi dengan bahan pangan dan cita rasa lokal.\n\nSoto Banjar umumnya menggunakan daging ayam yang disuwir dan kuah kaldu beraroma rempah, seperti kayu manis, cengkih, kapulaga, pala, serta lada. Hidangan ini biasanya disajikan bersama ketupat atau lontong, telur rebus, perkedel kentang, dan taburan bawang goreng. Perpaduan rempah dan kuah kaldunya menghasilkan cita rasa gurih serta aroma khas yang membedakannya dari berbagai jenis soto di Indonesia.\n\nSeiring waktu, Soto Banjar berkembang menjadi ikon kuliner Kalimantan Selatan dan menyebar ke berbagai wilayah Indonesia. Hidangan ini tidak hanya dinikmati sebagai makanan sehari-hari, tetapi juga disajikan dalam acara keluarga, perayaan keagamaan, dan berbagai kegiatan masyarakat. Keberadaannya mencerminkan kekayaan rempah serta proses akulturasi budaya yang membentuk identitas kuliner masyarakat Banjar.","gambar_url":"assets/images/masakan/soto_banjar.jpg","sumber":"Resep prototipe untuk pengembangan aplikasi; takaran dan langkah perlu diverifikasi dengan tradisi lokal."},{"id":"papeda","nama":"Papeda","daerah_asal":"Papua & Maluku","kategori":"Sagu","porsi":4,"waktu_menit":25,"deskripsi":"Bubur sagu kenyal yang disantap bersama ikan kuah kuning.","bahan":[{"nama":"Tepung sagu","takaran":"250 g"},{"nama":"Air dingin","takaran":"250 ml"},{"nama":"Air mendidih","takaran":"750 ml"},{"nama":"Garam","takaran":"secukupnya"}],"langkah":["Larutkan tepung sagu dengan air dingin hingga tidak menggumpal.","Didihkan air terpisah dan tambahkan sedikit garam bila diinginkan.","Tuangkan air mendidih perlahan ke larutan sagu sambil terus diaduk.","Aduk hingga berubah menjadi bening, kental, dan lengket.","Sajikan segera bersama ikan kuah kuning atau lauk berkuah."],"rempah_utama":[],"nilai_budaya":"Papeda merupakan makanan berbahan sagu yang penting dalam tradisi pangan di Papua dan Maluku.","fun_fact":"Papeda merupakan makanan tradisional khas Papua dan Maluku yang berbahan dasar tepung sagu. Makanan ini telah menjadi makanan pokok masyarakat di wilayah timur Indonesia sejak dahulu, terutama bagi masyarakat yang tinggal di daerah pesisir, rawa, dan sekitar hutan sagu. Berdasarkan penelitian Budaya Sagu di Papua dari Masa Prasejarah hingga Masa Kini yang diterbitkan dalam jurnal Naditira Widya oleh Badan Riset dan Inovasi Nasional (BRIN), budaya pengolahan sagu di Papua telah dikenal sejak masa prasejarah dan diwariskan secara turun-temurun. Papeda dikenal luas dalam tradisi masyarakat adat Sentani, Arso, dan Manokwari.\n\nPapeda dibuat dengan mencampurkan tepung sagu dengan air panas sambil diaduk hingga mengental dan berubah menjadi bubur berwarna putih bening dengan tekstur lengket. Rasanya yang cenderung tawar membuat papeda cocok disantap bersama ikan kuah kuning, biasanya berbahan ikan tongkol, serta sayuran. Cara pengolahan dan penyajiannya dapat berbeda di setiap daerah, sesuai dengan tradisi masyarakat setempat.\n\nBagi masyarakat Papua dan Maluku, papeda bukan sekadar makanan, tetapi juga memiliki nilai sosial dan budaya yang kuat. Hidangan ini kerap disajikan dalam acara adat dan upacara penting, serta menjadi simbol hubungan masyarakat dengan alam dan sumber pangan lokal. Tradisi mengolah sagu dan menyantap papeda yang terus diwariskan menjadikannya bagian penting dari identitas kuliner masyarakat di Indonesia timur.","gambar_url":"assets/images/masakan/papeda.jpg","sumber":"Resep prototipe untuk pengembangan aplikasi; takaran dan langkah perlu diverifikasi dengan tradisi lokal."},{"id":"chai-kue","nama":"Chai Kue","daerah_asal":"Pontianak, Kalimantan Barat","kategori":"Camilan","porsi":4,"waktu_menit":75,"deskripsi":"Kue kukus berkulit tipis dengan isian sayuran, seperti bengkuang atau kucai, yang populer dalam kuliner Tionghoa peranakan Pontianak.","bahan":[{"nama":"Tepung beras","takaran":"150 g"},{"nama":"Tepung tapioka","takaran":"50 g"},{"nama":"Air panas","takaran":"sekitar 250 ml"},{"nama":"Bengkuang parut atau kucai","takaran":"250 g"},{"nama":"Bawang putih","takaran":"3 siung"},{"nama":"Ebi kering","takaran":"2 sdm, opsional"},{"nama":"Garam dan lada","takaran":"secukupnya"},{"nama":"Minyak","takaran":"secukupnya"}],"langkah":["Tumis bawang putih dan ebi hingga harum, lalu masukkan bengkuang atau kucai dan bumbui.","Campurkan tepung beras dan tapioka, lalu tuangkan air panas sedikit demi sedikit sambil diaduk hingga menjadi adonan yang dapat dibentuk.","Ambil sedikit adonan, pipihkan, beri isian, lalu lipat dan rapatkan tepinya.","Letakkan chai kue di wadah kukusan yang telah diolesi minyak.","Kukus sekitar 10–15 menit atau hingga kulit matang.","Sajikan hangat dengan bawang putih goreng atau saus sesuai selera."],"rempah_utama":["Bawang putih"],"nilai_budaya":"Chai kue menjadi bagian dari ragam kuliner peranakan yang dikenal di Pontianak dan Kalimantan Barat.","fun_fact":"Chaikue atau chai kue, yang juga dikenal sebagai choi pan, merupakan makanan tradisional masyarakat Tionghoa yang populer di Pontianak dan Singkawang, Kalimantan Barat. Hidangan ini dibawa oleh masyarakat Tionghoa yang bermigrasi dari Tiongkok dan menetap di Nusantara. Nama chai kue berasal dari bahasa Tiochiu, sedangkan choi pan berasal dari bahasa Hakka. Keduanya memiliki makna yang berkaitan dengan kue sayur.\n\nChaikue dibuat dari kulit tipis berbahan tepung beras dan tepung tapioka atau sagu, dengan isian sayuran seperti bengkuang, kucai, talas, dan rebung. Umumnya, makanan ini dimasak dengan cara dikukus dan disajikan bersama bawang putih goreng serta saus sambal. Resep dan variasi isiannya berkembang menyesuaikan bahan yang tersedia dan selera masyarakat setempat.\n\nSeiring waktu, chaikue menjadi bagian penting dari kekayaan kuliner multikultural Kalimantan Barat. Makanan ini tidak hanya digemari masyarakat Tionghoa, tetapi juga dinikmati oleh berbagai kelompok masyarakat, termasuk sebagai menu sarapan dan hidangan berbuka puasa. Kehadirannya mencerminkan perpaduan tradisi kuliner Tionghoa dengan kehidupan masyarakat lokal di Pontianak dan Singkawang.","gambar_url":"assets/images/masakan/chai_kue.jpeg","sumber":"Resep prototipe untuk pengembangan aplikasi; takaran dan langkah perlu diverifikasi dengan tradisi lokal."},{"id":"soto-kudus","nama":"Soto Kudus","daerah_asal":"Kudus, Jawa Tengah","kategori":"Sup","porsi":4,"waktu_menit":60,"deskripsi":"Soto berkuah ringan yang biasanya menggunakan ayam atau kerbau dan disajikan dalam mangkuk kecil bersama pelengkap.","bahan":[{"nama":"Ayam atau daging kerbau","takaran":"500–700 g"},{"nama":"Air","takaran":"1,5 liter"},{"nama":"Bawang merah","takaran":"6 butir"},{"nama":"Bawang putih","takaran":"4 siung"},{"nama":"Kemiri","takaran":"2 butir"},{"nama":"Ketumbar","takaran":"1 sdt"},{"nama":"Jahe","takaran":"2 cm"},{"nama":"Serai","takaran":"1 batang"},{"nama":"Daun salam","takaran":"2 lembar"},{"nama":"Garam dan merica","takaran":"secukupnya"}],"langkah":["Rebus ayam atau daging hingga empuk; sisihkan kaldu dan suwir atau iris daging.","Haluskan bawang merah, bawang putih, kemiri, ketumbar, dan jahe.","Tumis bumbu halus hingga harum, lalu tambahkan serai dan daun salam.","Masukkan tumisan ke dalam kaldu dan didihkan perlahan sekitar 15 menit.","Bumbui dengan garam dan merica, lalu masukkan kembali daging.","Sajikan dalam mangkuk kecil bersama tauge, seledri, bawang goreng, dan nasi sesuai selera."],"rempah_utama":["Kemiri","Ketumbar","Jahe","Serai","Daun salam"],"nilai_budaya":"Soto Kudus dikenal sebagai kuliner khas Kudus; dalam tradisi setempat, penggunaan daging kerbau juga memiliki konteks sejarah dan budaya.","fun_fact":"Soto Kudus merupakan makanan tradisional khas Kabupaten Kudus, Jawa Tengah, yang berkembang dari tradisi kuliner masyarakat setempat. Sejarahnya berkaitan dengan Sunan Kudus, tokoh penyebar Islam di Jawa yang dikenal mengajarkan sikap toleransi terhadap pemeluk agama Hindu. Menurut cerita yang diwariskan secara turun-temurun, penggunaan daging kerbau sebagai pengganti daging sapi menjadi bentuk penghormatan kepada masyarakat Hindu yang menganggap sapi sebagai hewan suci. Kisah ini menjadi bagian penting dari filosofi budaya Soto Kudus, meskipun rincian sejarah kemunculannya belum dapat dipastikan sepenuhnya.\n\nSoto Kudus umumnya disajikan dalam mangkuk kecil dengan kuah bening kekuningan, berisi daging kerbau atau ayam, tauge, dan terkadang bihun. Kuahnya menggunakan aneka rempah, seperti bawang putih, bawang merah, ketumbar, dan merica, sehingga menghasilkan cita rasa gurih dan aroma yang khas. Hidangan ini biasanya disantap bersama nasi, sambal, serta perasan jeruk nipis.\n\nSeiring waktu, Soto Kudus menyebar ke berbagai daerah di Indonesia dan menjadi salah satu ikon kuliner Jawa Tengah. Selain keunikan rasa dan penyajiannya, makanan ini dikenal sebagai simbol akulturasi budaya dan toleransi antarumat beragama. Tradisi penggunaan daging kerbau tetap dipertahankan oleh sejumlah penjual di Kudus, sementara variasi berbahan ayam juga semakin populer.","gambar_url":"assets/images/masakan/soto_kudus.jpeg","sumber":"Resep prototipe untuk pengembangan aplikasi; takaran dan langkah perlu diverifikasi dengan tradisi lokal."},{"id":"dendeng-balado","nama":"Dendeng Balado","daerah_asal":"Minangkabau, Sumatera Barat","kategori":"Daging","porsi":null,"waktu_menit":null,"deskripsi":"Dendeng balado merupakan makanan tradisional khas Minangkabau, Sumatera Barat, terutama dikenal sebagai salah satu hidangan populer dari Padang.","bahan":[],"langkah":[],"rempah_utama":["Cabai","Bawang merah"],"nilai_budaya":"","fun_fact":"Dendeng balado merupakan makanan tradisional khas Minangkabau, Sumatera Barat, terutama dikenal sebagai salah satu hidangan populer dari Padang. Hidangan ini berkembang dari tradisi masyarakat Minangkabau dalam mengolah dan mengawetkan daging agar tahan lebih lama, terutama sebelum tersedianya teknologi pendingin modern. Daging diiris tipis, dikeringkan, lalu diolah menjadi hidangan yang lezat. Seiring waktu, teknik tersebut berpadu dengan tradisi penggunaan cabai dan rempah khas Minangkabau hingga menghasilkan dendeng balado yang dikenal saat ini.\n\nDendeng balado umumnya dibuat dari daging sapi yang diiris tipis, direbus atau dikeringkan, kemudian digoreng hingga teksturnya sesuai selera. Hidangan ini disajikan dengan sambal balado berbahan dasar cabai merah, bawang merah, dan garam yang memberikan cita rasa pedas serta gurih. Istilah balado merujuk pada cara pengolahan makanan dengan cabai, yang banyak ditemukan dalam tradisi kuliner Minangkabau.","gambar_url":"","sumber":"Data awal; resep belum tersedia."},{"id":"tekwan","nama":"Tekwan","daerah_asal":"Palembang, Sumatera Selatan","kategori":"Sup","porsi":null,"waktu_menit":null,"deskripsi":"Tekwan merupakan makanan tradisional khas Palembang, Sumatera Selatan, yang berkembang melalui akulturasi budaya masyarakat Palembang dan Tionghoa.","bahan":[],"langkah":[],"rempah_utama":[],"nilai_budaya":"","fun_fact":"Tekwan merupakan makanan tradisional khas Palembang, Sumatera Selatan, yang berkembang melalui akulturasi budaya masyarakat Palembang dan Tionghoa. Interaksi antarkomunitas tersebut turut memengaruhi perkembangan kuliner berbahan ikan yang kemudian disesuaikan dengan cita rasa lokal. Menurut kajian Kalpataru: Jurnal Sejarah dan Pembelajaran Sejarah (2022), nama tekwan populer dikaitkan dengan ungkapan bahasa Palembang “bekotek samo kawan”, yang berarti mengobrol bersama teman. Namun, asal-usul nama tersebut merupakan salah satu versi yang berkembang di masyarakat dan belum dipastikan secara historis.\n\nTekwan dibuat dari adonan ikan, biasanya ikan tenggiri atau ikan gabus, yang dicampur dengan tepung tapioka atau sagu, kemudian dibentuk menjadi bulatan kecil dan direbus. Hidangan ini disajikan dalam kuah kaldu udang yang gurih, dilengkapi soun, jamur kuping, irisan bengkuang, seledri, dan bawang goreng. Berbeda dengan pempek yang umumnya disajikan bersama kuah cuko, tekwan memiliki ciri khas berupa kuah bening hangat dengan aroma udang dan rempah.\n\nKini, tekwan menjadi salah satu ikon kuliner Palembang yang dinikmati masyarakat dari berbagai daerah di Indonesia. Hidangan ini tidak hanya memanfaatkan kekayaan hasil perikanan setempat, tetapi juga mencerminkan perpaduan budaya yang membentuk identitas kuliner Palembang. Tradisi menyantap tekwan bersama keluarga atau teman turut memperkuat maknanya sebagai hidangan yang identik dengan kehangatan dan kebersamaan.","gambar_url":"","sumber":"Data awal; resep belum tersedia."},{"id":"gulai-tempoyak-ikan-patin","nama":"Gulai Tempoyak Ikan Patin","daerah_asal":"Jambi","kategori":"Ikan","porsi":null,"waktu_menit":null,"deskripsi":"Ikan patin yang dimasak bersama tempoyak (durian fermentasi), khas Jambi.","bahan":[],"langkah":[],"rempah_utama":["Cabai","Kunyit","Bawang merah","Bawang putih","Serai"],"nilai_budaya":"","fun_fact":"Hidangan ini dibuat dari ikan patin yang dimasak bersama tempoyak, yaitu durian fermentasi yang memberikan cita rasa asam dan aroma khas. Bumbu yang digunakan biasanya meliputi cabai, kunyit, bawang merah, bawang putih, dan serai. Perpaduan bumbu tersebut menghasilkan rasa gurih, pedas, dan asam yang menjadi ciri utama gulai tempoyak ikan patin. Resepnya dapat berbeda-beda menurut kebiasaan keluarga dan daerah, termasuk dalam penggunaan air atau santan.\n\nKini, gulai tempoyak ikan patin menjadi salah satu ikon kuliner Provinsi Jambi yang disajikan dalam kehidupan sehari-hari, acara keluarga, pesta pernikahan, dan berbagai kegiatan masyarakat. Hidangan ini juga banyak dijual di rumah makan dan pasar kuliner setempat. Selain menawarkan cita rasa yang khas, gulai tempoyak ikan patin menunjukkan bagaimana masyarakat Jambi mempertahankan tradisi kuliner dengan memanfaatkan bahan pangan lokal.","gambar_url":"","sumber":"Data awal; resep belum tersedia."},{"id":"pendap","nama":"Pendap","daerah_asal":"Bengkulu","kategori":"Ikan","porsi":null,"waktu_menit":null,"deskripsi":"Pendap merupakan makanan tradisional khas Provinsi Bengkulu, khususnya dikenal di wilayah Bengkulu Selatan dan Kabupaten Kaur.","bahan":[],"langkah":[],"rempah_utama":["Cabai","Bawang merah","Bawang putih","Kunyit","Lengkuas"],"nilai_budaya":"","fun_fact":"Pendap merupakan makanan tradisional khas Provinsi Bengkulu, khususnya dikenal di wilayah Bengkulu Selatan dan Kabupaten Kaur. Makanan ini diwariskan secara turun-temurun oleh masyarakat setempat dan telah menjadi bagian dari identitas kuliner daerah tersebut sejak lama. Berdasarkan penelitian Nasfati Iktarastiwi dan Marwanti dalam jurnal Mudra: Jurnal Seni Budaya (2023), asal-usul pasti pendap dan pencipta pertamanya belum diketahui. Namun, hidangan ini telah dikenal setidaknya sejak beberapa generasi lalu dan kerap disajikan dalam acara keluarga maupun kegiatan masyarakat.\n\nPendap dibuat dari ikan laut yang dibumbui dengan rempah-rempah dan kelapa parut, kemudian dibungkus menggunakan daun talas serta daun pisang sebelum dimasak selama kurang lebih delapan jam. Bumbu yang digunakan antara lain cabai, bawang merah, bawang putih, kunyit, lengkuas, dan garam. Proses memasak yang lama membuat bumbu meresap ke dalam ikan, menghasilkan cita rasa gurih, pedas, dan aroma khas daun pembungkusnya.\n\nKini, pendap menjadi salah satu ikon kuliner Bengkulu yang dikenal sebagai lauk pendamping nasi dan oleh-oleh khas daerah. Hidangan ini juga memiliki nilai budaya karena resep dan teknik pembuatannya terus diwariskan dari satu generasi ke generasi berikutnya. Pendap bahkan dikenal sebagai salah satu makanan yang disukai Presiden Soekarno ketika menjalani pengasingan di Bengkulu pada 1938–1942, sehingga semakin memperkuat popularitasnya sebagai kuliner khas daerah tersebut.","gambar_url":"","sumber":"Data awal; resep belum tersedia."},{"id":"mi-tarempa","nama":"Mi Tarempa","daerah_asal":"Tarempa, Kepulauan Riau","kategori":"Mie","porsi":null,"waktu_menit":null,"deskripsi":"Mi Tarempa merupakan makanan tradisional khas Tarempa, ibu kota Kecamatan Siantan, Kabupaten Kepulauan Anambas, Provinsi Kepulauan Riau.","bahan":[],"langkah":[],"rempah_utama":["Bawang putih","Cabai"],"nilai_budaya":"","fun_fact":"Mi Tarempa merupakan makanan tradisional khas Tarempa, ibu kota Kecamatan Siantan, Kabupaten Kepulauan Anambas, Provinsi Kepulauan Riau. Hidangan ini berkembang di tengah kehidupan masyarakat Melayu pesisir yang dekat dengan hasil laut. Menurut Dinas Kebudayaan Provinsi Kepulauan Riau, mi ini diproduksi secara lokal di Tarempa dan menjadi salah satu kuliner khas daerah tersebut. Penggunaan mi yang dipadukan dengan ikan laut juga mencerminkan perpaduan tradisi kuliner Melayu dan pengaruh budaya Tionghoa.\n\nMi Tarempa dibuat menggunakan mi kuning berbentuk pipih dengan tekstur kenyal, yang dimasak bersama ikan tongkol atau ikan laut lainnya, telur, tauge, dan sawi. Bumbunya terdiri dari bawang putih, cabai, serta kecap yang menghasilkan perpaduan rasa gurih, pedas, dan sedikit manis. Hidangan ini memiliki tiga variasi penyajian, yaitu mi basah yang berkuah, mi lembap dengan sedikit kuah kental, dan mi kering yang lebih menyerupai mi goreng.\n\nSeiring waktu, Mi Tarempa menyebar ke berbagai daerah di Kepulauan Riau, termasuk Batam dan Tanjungpinang, serta dikenal oleh wisatawan dari luar daerah. Hidangan ini kini menjadi salah satu ikon kuliner Kepulauan Riau yang memperkenalkan kekayaan hasil laut dan tradisi memasak masyarakat pesisir. Popularitasnya juga membantu mempertahankan resep lokal sekaligus mendukung perkembangan usaha kuliner masyarakat setempat.","gambar_url":"","sumber":"Data awal; resep belum tersedia."},{"id":"bika-ambon","nama":"Bika Ambon","daerah_asal":"Medan, Sumatera Utara","kategori":"Kue","porsi":null,"waktu_menit":null,"deskripsi":"Bika Ambon merupakan kue tradisional yang terkenal sebagai oleh-oleh khas Kota Medan, Sumatera Utara, meskipun namanya sering membuat orang mengira kue ini berasal dari Ambon, Maluku.","bahan":[],"langkah":[],"rempah_utama":[],"nilai_budaya":"","fun_fact":"Bika Ambon merupakan kue tradisional yang terkenal sebagai oleh-oleh khas Kota Medan, Sumatera Utara, meskipun namanya sering membuat orang mengira kue ini berasal dari Ambon, Maluku. Menurut penelitian yang diterbitkan dalam Journal of Ethnic Foods pada 2019, asal-usul pasti Bika Ambon belum diketahui secara jelas. Salah satu versi yang populer menyebutkan bahwa kue ini mulai dikenal luas karena dijual di sekitar Jalan Ambon, kawasan Sei Kera, Medan. Bika Ambon juga diyakini terinspirasi dari kue bika atau bingka khas Melayu yang mengalami perkembangan dalam bahan dan teknik pembuatannya.\n\nBika Ambon dibuat menggunakan tepung tapioka, telur, gula, santan, dan bahan fermentasi seperti ragi. Proses fermentasi serta pemanggangan menghasilkan tekstur berongga menyerupai sarang lebah, dengan rasa manis, legit, dan aroma yang khas. Kini, Bika Ambon tersedia dalam berbagai varian rasa, seperti pandan, keju, cokelat, dan durian.\n\nSeiring waktu, Bika Ambon berkembang menjadi salah satu ikon kuliner Medan dan oleh-oleh yang banyak diburu wisatawan. Pusat penjualannya dikenal berada di kawasan Jalan Majapahit, Medan, yang berkembang pesat sejak dekade 1980-an. Popularitasnya tidak hanya mendukung usaha kuliner lokal, tetapi juga memperkenalkan kekayaan tradisi kue Indonesia kepada masyarakat luas.","gambar_url":"","sumber":"Data awal; resep belum tersedia."},{"id":"kerak-telor","nama":"Kerak Telor","daerah_asal":"Jakarta","kategori":"Camilan","porsi":null,"waktu_menit":null,"deskripsi":"Kerak telor merupakan makanan tradisional khas masyarakat Betawi dari Jakarta yang telah dikenal sejak zaman kolonial Belanda.","bahan":[],"langkah":[],"rempah_utama":["Bawang merah","Cabai","Kencur","Jahe"],"nilai_budaya":"","fun_fact":"Kerak telor merupakan makanan tradisional khas masyarakat Betawi dari Jakarta yang telah dikenal sejak zaman kolonial Belanda. Berdasarkan catatan Warisan Budaya Takbenda Indonesia dari Kementerian Pendidikan dan Kebudayaan, makanan ini menjadi bagian dari kekayaan kuliner Betawi yang diwariskan secara turun-temurun. Meskipun terdapat cerita rakyat mengenai kemunculannya dari kreativitas masyarakat Betawi dalam mengolah bahan pangan sederhana, waktu dan pencipta pertama kerak telor belum diketahui secara pasti.\n\nKerak telor dibuat dari beras ketan putih, telur ayam atau bebek, ebi (udang kering), dan kelapa parut sangrai yang dikenal sebagai serundeng. Bahan-bahan tersebut dimasak di atas wajan tanpa minyak, menggunakan bara arang hingga bagian bawahnya membentuk kerak yang gurih. Hidangan ini kemudian diberi taburan bawang merah goreng dan bumbu seperti cabai, kencur, jahe, serta merica. Perpaduan tekstur renyah, rasa gurih, dan aroma kelapa sangrai menjadi ciri khas kerak telor.\n\nKini, kerak telor menjadi salah satu ikon kuliner Jakarta yang sering dijumpai dalam festival budaya Betawi, perayaan ulang tahun Jakarta, dan kawasan wisata seperti Setu Babakan. Selain menjadi makanan tradisional yang digemari, kerak telor juga melambangkan identitas budaya masyarakat Betawi. Pemerintah Indonesia menetapkannya sebagai Warisan Budaya Takbenda pada 2014 untuk mendukung pengakuan dan pelestarian tradisi kuliner tersebut.","gambar_url":"","sumber":"Data awal; resep belum tersedia."},{"id":"karedok","nama":"Karedok","daerah_asal":"Jawa Barat","kategori":"Sayur","porsi":null,"waktu_menit":null,"deskripsi":"Karedok merupakan makanan tradisional khas masyarakat Sunda, Jawa Barat, yang berasal dari kebiasaan mengonsumsi lalapan atau sayuran segar.","bahan":[],"langkah":[],"rempah_utama":["Cabai","Bawang putih","Kencur","Daun Kemangi"],"nilai_budaya":"","fun_fact":"Karedok merupakan makanan tradisional khas masyarakat Sunda, Jawa Barat, yang berasal dari kebiasaan mengonsumsi lalapan atau sayuran segar. Salah satu cerita rakyat mengaitkan asal-usul karedok dengan Desa Karedok di Kecamatan Jatigede, Kabupaten Sumedang. Konon, pada masa pemerintahan Bupati Sumedang Pangeran Aria Soeria Atmaja (1882–1919), penduduk setempat menyajikan karedok terong kepadanya ketika ia beristirahat setelah menangkap ikan di Sungai Cimanuk. Hidangan tersebut disukai sang bupati, lalu dikenal luas hingga nama kampung itu dikaitkan dengan karedok. Namun, kisah ini merupakan tradisi lisan dan bukan satu-satunya penjelasan mengenai asal-usul hidangan tersebut.\n\nKaredok dibuat dari aneka sayuran mentah, seperti kacang panjang, mentimun, tauge, kol, terong, dan daun kemangi, yang disiram bumbu kacang. Bumbunya biasanya terdiri atas kacang tanah, cabai, bawang putih, kencur, gula merah, garam, dan terasi. Berbeda dengan lotek yang menggunakan sayuran matang atau rebus, ciri utama karedok adalah penggunaan sayuran mentah sehingga kesegarannya tetap terasa.\n\nKaredok bukan sekadar makanan, tetapi juga mencerminkan tradisi kuliner Sunda yang memanfaatkan hasil pertanian lokal. Kebiasaan mengonsumsi lalapan memiliki jejak sejarah panjang; kajian sejarawan kuliner Fadly Rahman menelusuri penyebutan hidangan sayuran mentah dan matang dalam prasasti Jawa abad ke-10 serta naskah Sunda abad ke-16. Kini, karedok tetap populer sebagai hidangan sehari-hari dan bagian dari identitas kuliner Jawa Barat.","gambar_url":"","sumber":"Data awal; resep belum tersedia."},{"id":"sate-maranggi","nama":"Sate Maranggi","daerah_asal":"Purwakarta, Jawa Barat","kategori":"Sate","porsi":null,"waktu_menit":null,"deskripsi":"Sate Maranggi merupakan kuliner khas Purwakarta, Jawa Barat, yang berkembang dari tradisi masyarakat setempat dalam mengolah daging menjadi sate berbumbu.","bahan":[],"langkah":[],"rempah_utama":[],"nilai_budaya":"","fun_fact":"Sate Maranggi merupakan kuliner khas Purwakarta, Jawa Barat, yang berkembang dari tradisi masyarakat setempat dalam mengolah daging menjadi sate berbumbu. Berdasarkan penelitian yang diterbitkan dalam jurnal Patanjala pada 2017, sate ini telah dijual di Kecamatan Plered sejak sekitar 1962 oleh seorang pedagang bernama Bustomi Sukmawirda, yang dikenal sebagai Mang Udeng. Ada pula cerita bahwa nama “Maranggi” berasal dari panggilan Mak Anggi, seorang penjual sate. Karena bukti sejarah tertulis mengenai asal-usul dan penamaannya masih terbatas, kisah-kisah tersebut sebaiknya dipahami sebagai versi sejarah berdasarkan keterangan para informan.\n\nSate Maranggi umumnya dibuat dari potongan daging sapi atau domba yang direndam dalam racikan bumbu sebelum dibakar di atas bara api. Bumbunya menggunakan rempah-rempah dan gula aren yang menghasilkan perpaduan rasa gurih, manis, serta aroma bakaran yang khas. Berbeda dari sate yang biasanya mengandalkan saus setelah dibakar, cita rasa Sate Maranggi sudah meresap ke dalam daging melalui proses perendaman bumbu. Penyajiannya dapat dilengkapi sambal tomat, sambal oncom, atau ketan bakar, bergantung pada daerah dan penjualnya.\n\nSeiring waktu, Sate Maranggi berkembang dari kuliner lokal menjadi salah satu identitas kuliner Kabupaten Purwakarta dan dikenal di berbagai daerah. Perkembangannya turut didukung oleh pedagang, promosi wisata, dan festival kuliner. Pada 2018, Sate Maranggi tercatat dalam Katalog Warisan Budaya Takbenda Indonesia untuk Provinsi Jawa Barat. Pengakuan tersebut membantu memperkuat upaya pelestarian kuliner tradisional sekaligus memperkenalkan kekayaan budaya Purwakarta kepada masyarakat luas.","gambar_url":"","sumber":"Data awal; resep belum tersedia."},{"id":"lumpia-semarang","nama":"Lumpia Semarang","daerah_asal":"Semarang, Jawa Tengah","kategori":"Camilan","porsi":null,"waktu_menit":null,"deskripsi":"Lumpia Semarang merupakan makanan tradisional khas Semarang, Jawa Tengah, yang berkembang melalui akulturasi budaya Tionghoa dan Jawa pada abad ke-19. Menurut buku Dari Sam Poo Kong ke Lunpia Semarang yang diterbitkan Balai Bahasa Jawa Tengah, sejarahnya dikaitkan dengan Tjoa Thay Joe, seorang pendatang dari Fujian, Tiongkok, dan Wasih (juga dikenal sebagai Mbok Wasih), seorang perempuan Jawa yang sama-sama berdagang makanan.","bahan":[],"langkah":[],"rempah_utama":[],"nilai_budaya":"","fun_fact":"Lumpia Semarang merupakan makanan tradisional khas Semarang, Jawa Tengah, yang berkembang melalui akulturasi budaya Tionghoa dan Jawa pada abad ke-19. Menurut buku Dari Sam Poo Kong ke Lunpia Semarang yang diterbitkan Balai Bahasa Jawa Tengah, sejarahnya dikaitkan dengan Tjoa Thay Joe, seorang pendatang dari Fujian, Tiongkok, dan Wasih (juga dikenal sebagai Mbok Wasih), seorang perempuan Jawa yang sama-sama berdagang makanan. Keduanya kemudian menggabungkan tradisi kuliner mereka dan menciptakan olahan yang menyesuaikan cita rasa masyarakat setempat. Kisah ini menjadi penjelasan populer mengenai asal-usul lumpia Semarang.\n\nLumpia Semarang memiliki ciri khas berupa kulit tipis yang membungkus isian utama rebung atau tunas bambu, biasanya dicampur telur, ayam, atau udang. Isiannya memiliki perpaduan rasa gurih dan sedikit manis. Lumpia dapat disajikan dalam bentuk goreng dengan kulit renyah maupun basah dengan tekstur lebih lembut. Hidangan ini umumnya disantap bersama saus kental, acar, daun bawang, dan cabai rawit. Perpaduan teknik membuat kulit lumpia dari tradisi Tionghoa dengan bahan serta selera lokal menjadikan makanan ini berbeda dari lumpia di daerah lain.\n\nSeiring perkembangannya, lumpia menjadi salah satu ikon kuliner sekaligus oleh-oleh terkenal dari Semarang. Usaha lumpia diwariskan lintas generasi, termasuk oleh keluarga yang berjualan di kawasan Gang Lombok. Pada 2014, Lumpia Semarang ditetapkan sebagai Warisan Budaya Takbenda Indonesia oleh pemerintah. Pengakuan tersebut memperkuat nilai lumpia bukan hanya sebagai makanan, tetapi juga sebagai bukti perpaduan budaya yang membentuk identitas masyarakat Semarang.","gambar_url":"","sumber":"Data awal; resep belum tersedia."},{"id":"tengkleng","nama":"Tengkleng","daerah_asal":"Solo, Jawa Tengah","kategori":"Sup","porsi":null,"waktu_menit":null,"deskripsi":"Olahan tulang, iga, kepala, kaki, dan jeroan kambing berkuah rempah, khas Solo.","bahan":[],"langkah":[],"rempah_utama":["Bawang merah","Bawang putih","Jahe","Kunyit","Serai","Lengkuas","Daun jeruk"],"nilai_budaya":"","fun_fact":"Tengkleng biasanya dibuat dari tulang, iga, kepala, kaki, dan jeroan kambing yang dimasak bersama berbagai rempah, seperti bawang merah, bawang putih, jahe, kunyit, serai, lengkuas, dan daun jeruk. Hidangan ini sekilas menyerupai gulai kambing, tetapi kuah tengkleng umumnya lebih encer dan memiliki rasa gurih dengan aroma rempah yang kuat. Daging yang masih menempel pada tulang serta sumsum di dalamnya menjadi bagian yang banyak dinikmati. Selain versi berkuah, terdapat pula tengkleng rica yang bercita rasa lebih pedas.\n\nNama “tengkleng” sering dikaitkan dengan bunyi kleng-kleng yang muncul ketika tulang kambing beradu dengan piring seng yang dahulu digunakan masyarakat. Kisah penamaan ini mencerminkan kehidupan sederhana masyarakat Solo pada masa lalu. Seiring waktu, tengkleng berkembang menjadi salah satu ikon kuliner Solo yang dijajakan di warung makan hingga pasar tradisional, termasuk kawasan Pasar Klewer. Kini, hidangan tersebut bukan hanya dikenal karena cita rasanya, tetapi juga karena kisah kreativitas masyarakat dalam memanfaatkan bahan pangan dan mengubah keterbatasan menjadi warisan kuliner.","gambar_url":"","sumber":"Data awal; resep belum tersedia."}];